from copy import deepcopy


def deep_merge(base, override):
    """Return an independent configuration with override layered over base."""
    result = {}
    for key, value in base.items():
        if key not in override:
            result[deepcopy(key)] = deepcopy(value)
        elif override[key] is not None:
            result[deepcopy(key)] = _override_value(value, override[key])

    for key, value in override.items():
        if key not in base and value is not None:
            result[deepcopy(key)] = _override_value(None, value)
    return result


def _override_value(base_value, value):
    if isinstance(value, dict):
        return deep_merge(base_value if isinstance(base_value, dict) else {}, value)
    return deepcopy(value)
